//! The host protocol's wire types (INTERFACES §6 to §8), generated by typify from
//! `@mostra/protocol`'s draft-07 schema and committed (D59, D143 item 3).
//!
//! Every type matches one definition of the schema. Unknown object fields are ignored, so a newer
//! instance's additions never break this release; every enum carries an `Unknown` variant that
//! keeps a value this release doesn't know and serializes it back unchanged. Times are the
//! RFC 3339 strings the instance sent.

use serde::Serialize;
use serde::de::DeserializeOwned;

#[allow(
    missing_docs,
    clippy::all,
    clippy::pedantic,
    unreachable_patterns,
    reason = "generated by typify"
)]
#[rustfmt::skip] // prettyplease formats it, so the snapshot never depends on a rustfmt release
mod generated;
#[rustfmt::skip]
pub mod methods;

pub use generated::*;

/// Generates a boolean that the schema fixes to one value (`const`): it reads only that value and
/// writes it back, so an untagged union told apart by it decodes as the right member.
macro_rules! boolean_constant {
    ($name:ident, $value:literal, $doc:literal) => {
        #[doc = $doc]
        #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
        pub struct $name;

        impl Serialize for $name {
            fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                serializer.serialize_bool($value)
            }
        }

        impl<'de> serde::Deserialize<'de> for $name {
            fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
                let value = bool::deserialize(deserializer)?;
                if value == $value {
                    Ok(Self)
                } else {
                    Err(serde::de::Error::custom(concat!(
                        "expected ",
                        stringify!($value)
                    )))
                }
            }
        }

        impl From<$name> for bool {
            fn from(_: $name) -> bool {
                $value
            }
        }
    };
}

boolean_constant!(
    ConstTrue,
    true,
    "`true`, where the schema allows no other value."
);
boolean_constant!(
    ConstFalse,
    false,
    "`false`, where the schema allows no other value."
);

/// Who sends a method's request.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Direction {
    /// A client asks the instance.
    ClientToInstance,
    /// The instance asks the host that registered a port.
    InstanceToHost,
}

/// One method of the host protocol, with its params and result types.
pub trait Method {
    /// The JSON-RPC method name.
    const NAME: &'static str;
    /// Who sends the request.
    const DIRECTION: Direction;
    /// Whether it changes durable state (and takes a `requestId`, H-03).
    const MUTATING: bool;
    /// Its params.
    type Params: Serialize + DeserializeOwned + Send + Sync + 'static;
    /// Its result.
    type Result: Serialize + DeserializeOwned + Send + Sync + 'static;
}

/// One notification the instance sends.
pub trait Notification {
    /// The JSON-RPC method name.
    const NAME: &'static str;
    /// Its params.
    type Params: Serialize + DeserializeOwned + Send + Sync + 'static;
}

/// A method's name and kind, for tables and checks.
#[derive(Clone, Copy, Debug)]
pub struct MethodInfo {
    /// The JSON-RPC method name.
    pub name: &'static str,
    /// Who sends the request.
    pub direction: Direction,
    /// Whether it changes durable state.
    pub mutating: bool,
}
